"""In-memory task store with validation. Stdlib only."""
from dataclasses import dataclass, field, asdict
from itertools import count

@dataclass
class Task:
    id: int
    title: str
    done: bool = False
    tags: list = field(default_factory=list)

class TaskStore:
    def __init__(self):
        self._ids = count(1)
        self._tasks = {}

    def add(self, title, tags=None):
        title = (title or "").strip()
        if not title:
            raise ValueError("title is required")
        t = Task(next(self._ids), title, tags=list(tags or []))
        self._tasks[t.id] = t
        return asdict(t)

    def complete(self, task_id):
        t = self._tasks.get(task_id)
        if t is None:
            raise KeyError(task_id)
        t.done = True
        return asdict(t)

    def list(self, done=None):
        return [asdict(t) for t in self._tasks.values() if done is None or t.done == done]
EOF
