import unittest
from tasks import TaskStore

class TestTaskStore(unittest.TestCase):
    def test_add_and_complete(self):
        s = TaskStore()
        t = s.add("  write report ", ["work"])
        self.assertEqual(t["title"], "write report")
        self.assertFalse(t["done"])
        self.assertTrue(s.complete(t["id"])["done"])

    def test_rejects_empty_title(self):
        with self.assertRaises(ValueError):
            TaskStore().add("   ")

    def test_filter(self):
        s = TaskStore()
        a = s.add("a"); s.add("b"); s.complete(a["id"])
        self.assertEqual(len(s.list(done=True)), 1)
        self.assertEqual(len(s.list(done=False)), 1)

if __name__ == "__main__":
    unittest.main()
EOF
