"""Moving-average demand forecast for daily covers/orders. Stdlib only."""
def moving_average_forecast(history, window=7):
    if window < 1:
        raise ValueError("window must be >= 1")
    if len(history) < window:
        raise ValueError("not enough history")
    return sum(history[-window:]) / window

def mape(actual, predicted):
    pairs = [(a, p) for a, p in zip(actual, predicted) if a]
    return 100 * sum(abs(a - p) / a for a, p in pairs) / len(pairs)

if __name__ == "__main__":
    data = [120, 135, 110, 150, 160, 140, 130, 125, 138, 152]
    print("next-day forecast:", round(moving_average_forecast(data, 7), 1))
EOF
