"""Restaurant food-cost tracker: ingredient prices -> cost per menu item and food-cost %."""
from dataclasses import dataclass, field

@dataclass
class Ingredient:
    name: str
    unit_price: float  # dollars per unit
    unit: str

@dataclass
class MenuItem:
    name: str
    price: float
    recipe: dict = field(default_factory=dict)  # ingredient name -> quantity used

def item_cost(item, ingredients):
    return sum(ingredients[n].unit_price * q for n, q in item.recipe.items())

def food_cost_pct(item, ingredients):
    return 100.0 * item_cost(item, ingredients) / item.price if item.price else 0.0

def report(items, ingredients):
    rows = []
    for it in items:
        c = item_cost(it, ingredients)
        rows.append((it.name, round(c, 2), it.price, round(food_cost_pct(it, ingredients), 1)))
    return sorted(rows, key=lambda r: -r[3])

if __name__ == "__main__":
    ing = {
        "flour": Ingredient("flour", 0.0008, "g"),
        "mozzarella": Ingredient("mozzarella", 0.012, "g"),
        "tomato": Ingredient("tomato", 0.004, "g"),
    }
    menu = [MenuItem("Margherita", 14.0, {"flour": 250, "mozzarella": 120, "tomato": 100})]
    for row in report(menu, ing):
        print("%-12s cost $%.2f  price $%.2f  food cost %.1f%%" % row)
EOF
